  EST.ROWS.forEach((Ys,r)=>[0,1].forEach(s=>{ const keys=EST.LAY[(r*2+s+ei*2)%6]; EST.UC.forEach((u,i)=>add(keys[ei%2?3-i:i],u,s?Ys+6:Ys-6,s?-1:1)); }));
