    h.ll.rotation.x=h.rl.rotation.x=0; h.lk.rotation.x=h.rk.rotation.x=.02; h.la.rotation.set(.04,0,.07); h.ra.rotation.set(.04,0,-.07); h.lel.rotation.x=-.12; h.rel.rotation.x=-.12;
