const camState={yaw:HOME0.ry,pitch:.26,zoom:1,last:-10,dist:4.3,shake:0}; camState.yaw=clearYaw(player.x,player.y,player.z,homeNow()==='tent'?HOME0.ry+2.5:HOME0.ry);   // at your door: a clear view, not your wall
