  const mixer=new THREE.AnimationMixer(C.tpl), yieldNow=()=>new Promise(r=>setTimeout(r,0)), Bs=parts.map(crowdBase), total=Bs.reduce((a,B)=>a+B.idx.length/3,0), want=Q.npc<=8?1500:2200;
