  for(let i=0;i<P.count;i++){ if(Math.abs(P.getZ(i))>.07) continue; const f=(P.getX(i)/L+.5)*(n-1), j=Math.round(f); if(j>=0&&j<n&&Math.abs(f-j)<.75) h[j]=Math.max(h[j],P.getY(i)); }
