    o.traverse(m=>{ if(m.isMesh){ if(m.material.map) m.material.map.colorSpace=THREE.SRGBColorSpace; m.material.roughness=.5; m.material.metalness=id==='ak'?.4:.6; m.castShadow=true; } });
