const HOLD={katana:{tilt:.35,edge:1,g:[0,0,-.035]},baton:{tilt:.25,edge:0,g:[.07,0,-.012]},gren:{tilt:0,edge:0,g:[0,0,0]},molo:{tilt:-1,edge:0,g:[0,0,.02]}};
