  const A=nodes[best.a], t=best.len*.5, sd=1, off=best.hw+17, x=A.x+best.fx*t-best.fz*off*sd, z=A.z+best.fz*t+best.fx*off*sd, nx=-best.fz*sd, nz=best.fx*sd;
