// ---- the mechanic: drive in, step out, talk to Baba; the car nearest the yard gets fixed
function garageCar(){ const c=gp('garage',0,0); let best=null, bd=1e9; for(const v of vehicles){ if(v.ai||v===RIDE.v||!(v.dmg>0||v.wreck)) continue; const d=Math.hypot(v.x-c.x,v.z-c.z)-(v.mine?15:0); if(d<30&&d<bd){ bd=d; best=v; } } return best; }
function garageMenu(){ const v=garageCar(); if(!v){ toast(mpick(['Mechanic: "Bring the car inside the yard first. Wetin spoil?"','Mechanic: "Your car no get problem. Na fuel you need?"']),3); return; }
  const nm=(VT[v.type]||{name:'car'}).name, cost=v.wreck?60000:Math.max(2000,Math.round((1500+(v.dmg||0)*300)/500)*500);
  openMenu('MECHANIC · IKEJA GRA','Baba Sule and his boys',[{name:`Fix the ${nm}`,sub:v.wreck?'Burnt and broken: new engine, panels and paint':`Damage ${Math.round(v.dmg)}%: panel beating, spraying, engine`,price:cost,
    act:()=>{ closeMenu(); fadeSwap(()=>{ unwreck(v); }); toast(mpick([`The boys work am sharp sharp. Your ${nm} don dey like new!`,`Panel beating, spraying, oil change. ${nm} ready!`]),3.5); }}]); }

/* ---- out in the street: who stands at the doors, footballers and fans at the stadium and the field */
const WFOLK={groups:[]};
function worldGroup(x,z,make){ WFOLK.groups.push({x,z,make,list:null,on:false}); }
function updateWorldFolk(dt){ if(!PEOPLE.n) return; for(const G of WFOLK.groups){ const d=Math.hypot(G.x-player.x,G.z-player.z);
    if(!G.list&&d<230){ G.list=[]; G.make(G); } if(!G.list) continue; const on=d<260; if(on!==G.on){ G.on=on; for(const f of G.list) f.root.visible=on; } if(!on) continue;
    if(G.tick) G.tick(dt); for(const f of G.list) if(Math.hypot(f.root.position.x-camera.position.x,f.root.position.z-camera.position.z)<120) f.mixer.update(dt); } }
for(const c of VENUES.clubs){ const r=c.r; worldGroup(c.x,c.z,G=>{ folk(scene,'areaboy',markAt(r,'bouncer_1'),['fight_idle','idle_1'],G.list); folk(scene,'areaboy',markAt(r,'bouncer_2'),['idle_1','phone'],G.list); }); }
if(STATION.r&&STATION.r.M.marks) worldGroup(STATION.x,STATION.z,G=>folk(scene,'police_m',markAt(STATION.r,'guard'),['idle_1','phone'],G.list));
if(VENUES.carstand) worldGroup(VENUES.carstand.x,VENUES.carstand.z,G=>folk(scene,'baba',markAt(VENUES.carstand.r,'salesman'),['talk','idle_baba'],G.list));
// football: players walk after the ball, the ball goes from foot to foot; fans wave in the stands
for(const r of [STADIUM,PITCH]){ if(!r) continue; worldGroup(r.x,r.z,G=>{ const pm=markAt(r,'pitch'), c=Math.cos(r.ry), s=Math.sin(r.ry), hw=Math.abs(pm.x1-pm.x0)/2*.9, hd=Math.abs(pm.y1-pm.y0)/2*.9;
    const toW=(u,v)=>({x:pm.x+u*c+v*s,z:pm.z-u*s+v*c}), kit=['schoolboy','areaboy','p_tunde','areaboy','schoolboy','areaboy','p_tunde','schoolboy','areaboy','areaboy'];
    const pl=marksOf(r,/^player_/).map((m,i)=>{ const f=folk(scene,kit[i%kit.length],m,['walk'],G.list); if(f){ f.u=(m.x-pm.x)*c-(m.z-pm.z)*s; f.v=(m.x-pm.x)*s+(m.z-pm.z)*c; f.home={u:f.u,v:f.v}; } return f; }).filter(Boolean);
    for(const m of marksOf(r,/^fan_/)){ const f=folk(scene,mpick(['areaboy','mama','baba','lady_red','schoolboy','p_ada']),{...m,y:0},['hail','idle_1','talk','f_idle'],G.list); if(f) f.root.position.y=m.y; }
    const ballM=new THREE.Mesh(new THREE.SphereGeometry(.12,10,8),new THREE.MeshStandardMaterial({color:0xf5f5f5,roughness:.6})); scene.add(ballM);
    const B={u:0,v:0,tu:0,tv:0,to:pl[0]||null}; G.list.push({root:ballM,mixer:{update(){}}});
    G.tick=dt=>{ if(!pl.length) return; if(B.to){ const du=B.to.u-B.u, dv=B.to.v-B.v, d=Math.hypot(du,dv); if(d<.6){ B.to=pl[Math.floor(Math.random()*pl.length)]; } else { const st=Math.min(d,9*dt); B.u+=du/d*st; B.v+=dv/d*st; } }
      for(const f of pl){ const near=f===B.to, tu=near?B.u:f.home.u+(B.u-f.home.u)*.35, tv=near?B.v:f.home.v+(B.v-f.home.v)*.35, du=tu-f.u, dv=tv-f.v, d=Math.hypot(du,dv);
        if(d>.8){ const st=Math.min(d,(near?2.2:1.4)*dt); f.u=clamp(f.u+du/d*st,-hw,hw); f.v=clamp(f.v+dv/d*st,-hd,hd); }
        const w=toW(f.u,f.v); f.root.position.set(w.x,0,w.z); f.root.rotation.y=Math.atan2(du*c+dv*s,-du*s+dv*c); }
      const w=toW(B.u,B.v); ballM.position.set(w.x,.12,w.z); }; }); }
// the doors you walk into from the street
for(const h of HOTELS) if(h.i) DOORS.push({x:h.door.x,z:h.door.z,r:2.2,label:'Enter '+h.name,act:()=>enterLobby(h.i)});
for(const c of VENUES.clubs){ DOORS.push({x:c.door.x,z:c.door.z,r:2.2,label:()=>CLUB.paid===c.i?'Enter '+c.name:`Enter ${c.name} (gate fee ${naira(CLUB.fee)})`,act:()=>enterClub(c)});
  PLACES.push({name:c.name,sub:'Night club · DJ, bar and dance floor',kind:'club',x:c.x,z:c.z}); }
if(STATION.r&&STATION.r.M.marks) DOORS.push({x:STATION.front.x,z:STATION.front.z,r:2.2,label:'Enter the police station',act:enterPolice});
if(VENUES.carstand){ const V=VENUES.carstand; DOORS.push({x:V.door.x,z:V.door.z,r:2.2,label:'Enter the car showroom',act:enterShowroom});
  PLACES.push({name:'Oluwaseun Motors',sub:'Car stand · tokunbo and brand new cars',kind:'cars',x:V.x,z:V.z}); }
// ---- the car catalogue at the car stand: every new car class by class, delivered to the kerb outside
function buyNewCar(N){ // the menu takes the money before calling this
  if(PH) PH.event('carbuy',{}); OWNED.push({type:N.k,color:'#ffffff',name:N.n}); saveOwned(); closeMenu();
  const at=VENUES.carstand?VENUES.carstand.door:player; spawnOwned(OWNED[OWNED.length-1],at); toast(`Congrats! Your ${N.n} dey wait for you outside. Press E to drive.`,4); }
function openCarCatalog(){ const rows=[]; for(const c of ['Everyday','Mid','SUV','Luxury','Super-luxury']) for(const N of NEWV) if(N.c===c&&N.price)
    rows.push({name:N.n,sub:`${N.c} · top speed ${Math.round(N.v[1]*3.6*1.25)} km/h`,price:N.price,btn:naira(N.price),act:()=>buyNewCar(N)});
  openMenu('NAIJA MOTORS CATALOGUE','Brand new, any class. Delivered to the kerb outside',rows); }
if(VENUES.carstand){ const V=VENUES.carstand; DOORS.push({x:V.door.x+2.6,z:V.door.z,r:1.8,label:'Car catalogue: buy any car',act:openCarCatalog}); }
// ---- where to go in: a pulsing ring and a bobbing arrow at every door you can walk into (hotels, clubs, police, car stand)
const DMARK={list:[],arrowG:(()=>{ const g=new THREE.ConeGeometry(.32,.62,4); g.rotateX(Math.PI); g.rotateY(Math.PI/4); return g; })(),t:0};
function doorMark(x,z,col,text,txt2){ const y=groundY(x,z), c=new THREE.Color(col), g=new THREE.Group(); g.position.set(x,y,z); g.layers.set(1);
  const ring=new THREE.Mesh(new THREE.RingGeometry(1.05,1.35,48),new THREE.MeshBasicMaterial({color:c,transparent:true,opacity:.8,depthWrite:false,fog:false})); ring.rotation.x=-Math.PI/2; ring.position.y=Math.max(0,SLAB-y)+.08; ring.renderOrder=2;   // on top of the pavement ring.layers.set(1); g.add(ring);
  const arrow=new THREE.Mesh(DMARK.arrowG,new THREE.MeshBasicMaterial({color:c,fog:false})); arrow.position.y=2.5; arrow.layers.set(1); g.add(arrow);
  let lab=null; if(text){ lab=new THREE.Sprite(new THREE.SpriteMaterial({map:texLabel(text,col,'#0E1014'),transparent:true,fog:false})); lab.scale.set(4.6,.86,1); lab.position.y=3.5; lab.layers.set(1); g.add(lab); }
  scene.add(g); const m={x,z,g,ring,arrow,lab,text,col}; DMARK.list.push(m); return m; }
// the ring sits on whatever is under the door: a hotel's raised forecourt, steps, the pavement (once, when you first come near)
const _dmRay=new THREE.Raycaster(); _dmRay.layers.enableAll();
function doorMarkFloor(m){ try{ _dmRay.set(new THREE.Vector3(m.x,m.g.position.y+1.6,m.z),new THREE.Vector3(0,-1,0)); _dmRay.far=2.4; const hits=[], tmp=new THREE.Mesh();
  for(const c of CULLS){ if(c.off||!c.levels[0]) continue; for(const it of c.items){ if(Math.abs(it.x-m.x)>60||Math.abs(it.z-m.z)>60||!it.m) continue; tmp.geometry=c.levels[0].geo; tmp.matrixWorld.fromArray(it.m); tmp.raycast(_dmRay,hits); } }
  let top=-1e9; for(const h of hits) if(h.point.y<m.g.position.y+1.5) top=Math.max(top,h.point.y);
  if(top>m.g.position.y+.05) m.ring.position.y=top-m.g.position.y+.06; }catch(e){ console.warn(e); } }
function doorMarkText(m,text){ if(!m.lab||m.text===text) return; m.text=text; const old=m.lab.material.map; m.lab.material.map=texLabel(text,m.col,'#0E1014'); m.lab.material.needsUpdate=true; if(old) old.dispose(); }
function doorMarksTick(dt){ DMARK.t+=dt; const k=Math.sin(DMARK.t*3), px=mode==='drive'&&drive.v?drive.v.x:player.x, pz=mode==='drive'&&drive.v?drive.v.z:player.z;
  if((DMARK.lab=(DMARK.lab||0)-dt)<=0){ DMARK.lab=1; for(const h of HOTELS) if(h.mark) doorMarkText(h.mark,STAY&&STAY.h===h.i?`YOUR HOTEL · ROOM ${roomNo(stayTier().f,STAY.n)}`:h.markTxt); }
  for(const m of DMARK.list){ const d=Math.hypot(m.x-px,m.z-pz); m.g.visible=d<120&&mode!=='interior'; if(!m.g.visible) continue;
    if(!m.fixed&&d<90){ m.fixed=true; doorMarkFloor(m); }
    if(m.near){ const sh=d>m.near; m.arrow.visible=sh; if(m.lab) m.lab.visible=sh; }
    m.ring.material.opacity=.5+.3*k; m.ring.scale.setScalar(1+.07*k); m.arrow.position.y=2.45+.22*Math.sin(DMARK.t*2.4); m.arrow.rotation.y=DMARK.t*1.6; } }
